1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"os"
12		"os/exec"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	
18		"github.com/spf13/cobra"
19	)
20	
21	const (
22		distillCacheFileName    = "distill-cache.json"
23		distillCachePath        = factsDirName + "/" + distillCacheFileName
24		distillCacheVersion     = 1
25		defaultDistillChunkSize = 48 * 1024
26		defaultDistillTimeout   = 10 * time.Minute
27		distillDefaultBranch    = "main"
28		// maxDistillWarnings bounds the warning list so a systemic failure (e.g.
29		// every agent call failing) cannot balloon the manifest with one warning
30		// per chunk.
31		maxDistillWarnings = 50
32	)
33	
34	// capWarnings truncates a warning list to max entries, replacing the overflow
35	// with a single summary line so a systemic failure stays legible.
36	func capWarnings(warnings []string, max int) []string {
37		if len(warnings) <= max {
38			return warnings
39		}
40		extra := len(warnings) - max
41		out := append(warnings[:max:max], fmt.Sprintf("... and %d more warnings (suppressed)", extra))
42		return out
43	}
44	
45	// distillAgentRunner executes the seed agent with the distillation prompt for
46	// one transcript chunk and returns the agent's raw stdout. It is injected so
47	// the orchestration can be tested with a fake agent (the real implementation,
48	// execDistillAgent, shells out).
49	type distillAgentRunner func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error)
50	
51	type distillCommandOptions struct {
52		branch              string
53		force               bool
54		json                bool
55		agent               string
56		agentCommand        []string
57		timeout             time.Duration
58		maxChunkBytes       int
59		confidenceThreshold float64
60		run                 distillAgentRunner
61	}
62	
63	// transcriptChunk is a line-numbered slice of one session transcript handed to
64	// the agent. StartLine is the 1-based line offset of the chunk's first line in
65	// the original transcript, used as the chunk's provenance anchor in Phase A.
66	type transcriptChunk struct {
67		StartLine int
68		EndLine   int
69		Text      string
70	}
71	
72	// distillCache memoizes the fingerprint of each session that has been
73	// distilled, so an incremental run skips sessions whose transcript and
74	// checkpoint are unchanged.
75	type distillCache struct {
76		Version  int               `json:"version"`
77		Sessions map[string]string `json:"sessions"`
78	}
79	
80	func newDistillCommand(opts Options) *cobra.Command {
81		distillOpts := distillCommandOptions{agent: "auto", timeout: defaultDistillTimeout, maxChunkBytes: defaultDistillChunkSize, confidenceThreshold: defaultFactConfidenceThreshold}
82		cmd := &cobra.Command{
83			Use:   "distill [path]",
84			Short: "Distill captured sessions into durable facts (agent-required)",
85			Args:  cobra.MaximumNArgs(1),
86			RunE: func(cmd *cobra.Command, args []string) error {
87				target := "."
88				if opts.Env.RepoRoot != "" {
89					target = opts.Env.RepoRoot
90				}
91				if len(args) == 1 {
92					target = args[0]
93				}
94				return runDistill(cmd.Context(), cmd, opts, distillOpts, target)
95			},
96		}
97		cmd.Flags().StringVar(&distillOpts.branch, "branch", "", "Limit distillation to a single branch (default: all exported branches)")
98		cmd.Flags().BoolVar(&distillOpts.force, "force", false, "Recompute all distilled facts from scratch instead of skipping unchanged sessions")
99		cmd.Flags().BoolVar(&distillOpts.json, "json", false, "Emit the fact source summary as JSON")
100		cmd.Flags().StringVar(&distillOpts.agent, "agent", "auto", "Distillation agent: auto, codex, claude-code, or command")
101		cmd.Flags().StringArrayVar(&distillOpts.agentCommand, "agent-command", nil, "Agent command argv for --agent command")
102		cmd.Flags().Float64Var(&distillOpts.confidenceThreshold, "confidence", defaultFactConfidenceThreshold, "Minimum agent confidence to auto-apply a merge/supersede; below this it is queued for review")
103		return cmd
104	}
105	
106	func runDistill(ctx context.Context, cmd *cobra.Command, opts Options, distillOpts distillCommandOptions, target string) error {
107		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
108		if err != nil {
109			return err
110		}
111		if !local {
112			return fmt.Errorf("distill requires a local repository path: %s", target)
113		}
114		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
115		if err != nil {
116			return err
117		}
118		if distillOpts.agent == "auto" {
119			distillOpts.agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
120		}
121		if distillOpts.agent == "none" {
122			return errors.New("distillation requires an agent (codex or claude-code); none found on PATH")
123		}
124		if distillOpts.run == nil {
125			distillOpts.run = execDistillAgent
126		}
127		source, err := runDistillForBrain(ctx, repoDir, storage.BrainDir, distillOpts, opts.Now().UTC())
128		if err != nil {
129			return err
130		}
131		if distillOpts.json {
132			data, err := json.MarshalIndent(source, "", "  ")
133			if err != nil {
134				return err
135			}
136			fmt.Fprintln(cmd.OutOrStdout(), string(data))
137			return nil
138		}
139		fmt.Fprintf(cmd.OutOrStdout(), "distilled %d facts (%d distilled, %d authored, %d superseded) across %d branch(es) from %d chunks; %d proposals queued for review\n",
140			source.Facts, source.Distilled, source.Authored, source.Superseded, len(source.Branches), source.ChunksScanned, source.Proposals)
141		return nil
142	}
143	
144	// runDistillForBrain is the agent-driven distillation engine, operating on an
145	// already-exported brain directory. It enumerates sessions chronologically,
146	// chunks each transcript, runs the agent per chunk, merges the resulting facts
147	// into per-branch stores, and records the fact source on the brain manifest.
148	// repoDir is the working directory the agent runs in (sandboxed read-only).
149	func runDistillForBrain(ctx context.Context, repoDir, brainDir string, distillOpts distillCommandOptions, now time.Time) (*factSourceManifest, error) {
150		manifest, err := loadBrainManifest(brainDir)
151		if err != nil {
152			return nil, err
153		}
154		if manifest.Sources == nil || manifest.Sources.Sessions == nil || len(manifest.Sources.Sessions.Sessions) == 0 {
155			return nil, errors.New("no exported sessions; run `entire brain refresh` first")
156		}
157		if distillOpts.run == nil {
158			return nil, errors.New("distill: no agent runner configured")
159		}
160		if distillOpts.maxChunkBytes <= 0 {
161			distillOpts.maxChunkBytes = defaultDistillChunkSize
162		}
163	
164		taxonomy, err := loadFactTaxonomy(brainDir, now)
165		if err != nil {
166			return nil, err
167		}
168		prompt, err := renderDistillPrompt(taxonomy)
169		if err != nil {
170			return nil, err
171		}
172		args, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, prompt)
173		if err != nil {
174			return nil, err
175		}
176		reconcileArgs, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, reconcilePrompt())
177		if err != nil {
178			return nil, err
179		}
180		threshold := distillOpts.confidenceThreshold
181		if threshold <= 0 {
182			threshold = defaultFactConfidenceThreshold
183		}
184	
185		sessions := append([]exportSession(nil), manifest.Sources.Sessions.Sessions...)
186		// Chronological order so any future supersession chain reconstructs
187		// deterministically regardless of incremental vs --force.
188		sort.SliceStable(sessions, func(i, j int) bool { return sessions[i].CreatedAt.Before(sessions[j].CreatedAt) })
189	
190		prevCache := loadDistillCache(brainDir)
191		newCache := distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(sessions))}
192	
193		byBranch := map[string][]factRecord{}
194		proposalsByBranch := map[string][]factProposal{}
195		loaded := map[string]bool{}
196		var warnings []string
197		chunksScanned, chunksDistilled := 0, 0
198	
199		// ensureBranch lazily loads a branch's existing facts. On --force the
200		// previously distilled facts are dropped so they are rebuilt from scratch;
201		// authored facts are always preserved.
202		ensureBranch := func(branch string) {
203			if loaded[branch] {
204				return
205			}
206			existing, loadErr := loadFacts(brainDir, branch)
207			if loadErr != nil {
208				warnings = append(warnings, fmt.Sprintf("load facts for %s: %v", branch, loadErr))
209			}
210			if distillOpts.force {
211				kept := existing[:0]
212				for _, record := range existing {
213					if record.Origin != factOriginDistilled {
214						kept = append(kept, record)
215					}
216				}
217				existing = kept
218			}
219			byBranch[branch] = existing
220			loaded[branch] = true
221		}
222	
223		for _, session := range sessions {
224			if distillOpts.branch != "" && session.Branch != distillOpts.branch {
225				continue
226			}
227			branch := session.Branch
228			if branch == "" {
229				branch = strings.TrimSpace(manifest.DefaultBranch)
230			}
231			if branch == "" {
232				branch = distillDefaultBranch
233			}
234			ensureBranch(branch)
235	
236			fingerprint := distillSessionFingerprint(session)
237			if !distillOpts.force {
238				if prev, ok := prevCache.Sessions[session.SessionID]; ok && prev == fingerprint {
239					newCache.Sessions[session.SessionID] = prev // unchanged; retain in cache and keep existing facts
240					continue
241				}
242			}
243	
244			content, readErr := readBrainRelativeFile(brainDir, session.TranscriptPath)
245			if readErr != nil {
246				warnings = append(warnings, fmt.Sprintf("read transcript %s: %v", session.TranscriptPath, readErr))
247				continue // not cached: retried next run
248			}
249			chunks := chunkTranscript(content, distillOpts.maxChunkBytes)
250			sessionFailed := false
251			for _, chunk := range chunks {
252				chunksScanned++
253				anchor := factAnchor{
254					SessionID:    session.SessionID,
255					CheckpointID: session.LatestCheckpoint,
256					Transcript:   filepath.ToSlash(session.TranscriptPath),
257					Line:         chunk.StartLine,
258				}
259				out, runErr := distillOpts.run(ctx, repoDir, args, []byte(chunk.Text), distillOpts.timeout)
260				if runErr != nil {
261					warnings = append(warnings, fmt.Sprintf("agent failed on %s:%d: %v", session.SessionID, chunk.StartLine, runErr))
262					sessionFailed = true
263					continue
264				}
265				records, chunkWarnings := distilledFactsFromOutput(out, taxonomy, anchor, branch, now)
266				warnings = append(warnings, chunkWarnings...)
267				if len(records) == 0 {
268					continue
269				}
270				chunksDistilled++
271				// Reconcile the chunk's candidates against the branch's active facts
272				// so near-duplicates merge and contradictions supersede instead of
273				// piling up. Low-confidence decisions are queued for review.
274				actions, recWarnings := reconcileChunkCandidates(ctx, distillOpts.run, reconcileArgs, records, byBranch[branch], repoDir, distillOpts.timeout)
275				warnings = append(warnings, recWarnings...)
276				var chunkProposals []factProposal
277				byBranch[branch], chunkProposals = applyFactActions(byBranch[branch], actions, threshold, now)
278				proposalsByBranch[branch] = append(proposalsByBranch[branch], chunkProposals...)
279			}
280			// Only cache a session as distilled when every chunk succeeded, so a
281			// session whose agent calls failed is retried on the next run rather
282			// than being silently treated as done.
283			if !sessionFailed {
284				newCache.Sessions[session.SessionID] = fingerprint
285			}
286		}
287	
288		warnings = capWarnings(warnings, maxDistillWarnings)
289	
290		totalProposals := 0
291		for branch, records := range byBranch {
292			if err := writeFacts(brainDir, branch, records); err != nil {
293				return nil, err
294			}
295			// Union this run's proposals with any already queued (a --force rebuild
296			// starts fresh since it rebuilds the distilled facts), then persist.
297			var prior []factProposal
298			if !distillOpts.force {
299				if loadedProposals, loadErr := loadFactProposals(brainDir, branch); loadErr != nil {
300					warnings = append(warnings, fmt.Sprintf("load proposals for %s: %v", branch, loadErr))
301				} else {
302					prior = loadedProposals
303				}
304			}
305			merged := dedupeProposals(append(prior, proposalsByBranch[branch]...))
306			if err := writeFactProposals(brainDir, branch, merged); err != nil {
307				return nil, err
308			}
309			totalProposals += len(merged)
310		}
311		if err := writeFactTaxonomy(brainDir, taxonomy); err != nil {
312			return nil, err
313		}
314		saveDistillCache(brainDir, newCache)
315	
316		source := summarizeFactSource(now, byBranch, chunksScanned, chunksDistilled, totalProposals, warnings)
317		if manifest.Sources == nil {
318			manifest.Sources = &brainSources{}
319		}
320		manifest.Sources.Facts = source
321		if manifest.GeneratedAt.IsZero() {
322			manifest.GeneratedAt = now
323		}
324		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
325			return nil, err
326		}
327		return source, nil
328	}
329	
330	// chunkTranscript splits a transcript into line-numbered chunks no larger than
331	// maxBytes (measured on the rendered, line-numbered text). A single line that
332	// exceeds maxBytes still becomes its own chunk rather than being dropped, so no
333	// content is silently lost. Blank input yields no chunks.
334	func chunkTranscript(content string, maxBytes int) []transcriptChunk {
335		if maxBytes <= 0 {
336			maxBytes = defaultDistillChunkSize
337		}
338		lines := strings.Split(content, "\n")
339		var chunks []transcriptChunk
340		var buf strings.Builder
341		startLine := 0
342		lineNo := 0
343		flush := func(endLine int) {
344			if buf.Len() == 0 {
345				return
346			}
347			chunks = append(chunks, transcriptChunk{StartLine: startLine, EndLine: endLine, Text: buf.String()})
348			buf.Reset()
349			startLine = 0
350		}
351		for _, line := range lines {
352			lineNo++
353			if strings.TrimSpace(line) == "" {
354				continue
355			}
356			rendered := fmt.Sprintf("%d\t%s\n", lineNo, line)
357			if buf.Len() > 0 && buf.Len()+len(rendered) > maxBytes {
358				flush(lineNo - 1)
359			}
360			if buf.Len() == 0 {
361				startLine = lineNo
362			}
363			buf.WriteString(rendered)
364		}
365		flush(lineNo)
366		return chunks
367	}
368	
369	// distillSessionFingerprint is the incremental-skip signal for one session.
370	// Session transcripts are content-stable across refreshes, so the session id
371	// plus its latest checkpoint and transcript path is a reliable change marker.
372	func distillSessionFingerprint(session exportSession) string {
373		sum := sha256.Sum256([]byte(strings.Join([]string{
374			session.SessionID,
375			session.LatestCheckpoint,
376			filepath.ToSlash(session.TranscriptPath),
377			session.Branch,
378		}, "\x00")))
379		return "sha256:" + hex.EncodeToString(sum[:])
380	}
381	
382	// readBrainRelativeFile reads a brain-relative path, rejecting absolute paths
383	// and parent-directory escapes so a manifest-supplied path cannot read outside
384	// the brain directory.
385	func readBrainRelativeFile(brainDir, rel string) (string, error) {
386		clean := filepath.Clean(filepath.FromSlash(rel))
387		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
388			return "", fmt.Errorf("unsafe transcript path: %s", rel)
389		}
390		data, err := os.ReadFile(filepath.Join(brainDir, clean))
391		if err != nil {
392			return "", err
393		}
394		return string(data), nil
395	}
396	
397	// loadDistillCache reads the incremental cache, always returning a usable value:
398	// any read/parse error or version mismatch yields an empty cache so the next
399	// run simply re-distills everything.
400	func loadDistillCache(brainDir string) distillCache {
401		empty := distillCache{Version: distillCacheVersion, Sessions: map[string]string{}}
402		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)))
403		if err != nil {
404			return empty
405		}
406		var cache distillCache
407		if err := json.Unmarshal(data, &cache); err != nil || cache.Version != distillCacheVersion || cache.Sessions == nil {
408			return empty
409		}
410		return cache
411	}
412	
413	// saveDistillCache persists the incremental cache. Failure is non-fatal: a
414	// missing cache only costs a full re-distillation next run.
415	func saveDistillCache(brainDir string, cache distillCache) {
416		data, err := json.MarshalIndent(cache, "", "  ")
417		if err != nil {
418			return
419		}
420		dir := filepath.Join(brainDir, factsDirName)
421		if err := os.MkdirAll(dir, 0o700); err != nil {
422			return
423		}
424		_ = writeFileAtomic(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)), append(data, '\n'), 0o600)
425	}
426	
427	// execDistillAgent is the real distillAgentRunner: it runs the agent with the
428	// transcript chunk on stdin and returns stdout, bounded by a timeout and an
429	// output-size cap.
430	func execDistillAgent(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
431		if len(args) == 0 {
432			return "", errors.New("distill: empty agent command")
433		}
434		runCtx, cancel := context.WithTimeout(ctx, timeout)
435		defer cancel()
436		command := exec.CommandContext(runCtx, args[0], args[1:]...)
437		command.Dir = dir
438		command.Stdin = bytes.NewReader(input)
439		var stdout, stderr bytes.Buffer
440		command.Stdout = &stdout
441		command.Stderr = &stderr
442		err := command.Run()
443		if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
444			return "", fmt.Errorf("agent timed out after %s", timeout)
445		}
446		if err != nil {
447			warning := strings.TrimSpace(stderr.String())
448			if warning == "" {
449				warning = strings.TrimSpace(stdout.String())
450			}
451			return "", fmt.Errorf("agent failed: %w: %s", err, truncateAgentWarning(warning))
452		}
453		if stdout.Len() > distillMaxOutputBytes {
454			return "", fmt.Errorf("agent output exceeds %d bytes", distillMaxOutputBytes)
455		}
456		return stdout.String(), nil
457	}
