1	package cli
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7		"strings"
8		"time"
9	
10		entirebrain "github.com/ashtom/entire-brain"
11	)
12	
13	const (
14		distillTemplateName    = "templates/entire-brain-distill.md"
15		distillTaxonomyMarker  = "${TAXONOMY_BLOCK}"
16		distillMaxOutputBytes  = 256 * 1024
17		distillFactMaxTextSize = 2000
18	)
19	
20	// distillTemplate returns the distillation prompt body shipped with the binary,
21	// with its YAML frontmatter stripped. The frontmatter is metadata for skill
22	// installers, not part of the prompt — and crucially the agent runners pass the
23	// prompt as a positional CLI argument, so a leading "---" would be parsed as an
24	// unknown flag and rejected. A missing template is a build error, not runtime.
25	func distillTemplate() (string, error) {
26		data, err := entirebrain.Templates.ReadFile(distillTemplateName)
27		if err != nil {
28			return "", fmt.Errorf("read distill template: %w", err)
29		}
30		return stripTemplateFrontmatter(string(data)), nil
31	}
32	
33	// stripTemplateFrontmatter removes a leading YAML frontmatter block
34	// ("---\n...\n---\n") and returns the body. Content without frontmatter is
35	// returned unchanged.
36	func stripTemplateFrontmatter(content string) string {
37		if !strings.HasPrefix(content, "---\n") && !strings.HasPrefix(content, "---\r\n") {
38			return content
39		}
40		lines := strings.Split(content, "\n")
41		for i := 1; i < len(lines); i++ {
42			if strings.TrimSpace(lines[i]) == "---" {
43				return strings.TrimLeft(strings.Join(lines[i+1:], "\n"), "\n")
44			}
45		}
46		return content // no closing delimiter; leave as-is
47	}
48	
49	// renderDistillPrompt substitutes the active taxonomy into the template's
50	// ${TAXONOMY_BLOCK} marker. The rendered prompt is what gets passed to the seed
51	// agent as its system prompt; the line-numbered transcript chunk is the input.
52	func renderDistillPrompt(taxonomy factTaxonomy) (string, error) {
53		template, err := distillTemplate()
54		if err != nil {
55			return "", err
56		}
57		if !strings.Contains(template, distillTaxonomyMarker) {
58			return "", fmt.Errorf("distill template missing %s marker", distillTaxonomyMarker)
59		}
60		return strings.ReplaceAll(template, distillTaxonomyMarker, factTaxonomyBlock(taxonomy)), nil
61	}
62	
63	// factTaxonomyBlock renders the taxonomy as the prompt section the agent uses to
64	// classify facts: the fixed top-level categories and the known three-level
65	// paths with descriptions. Output is deterministic (sorted) so the rendered
66	// prompt is stable across runs.
67	func factTaxonomyBlock(taxonomy factTaxonomy) string {
68		var b strings.Builder
69		b.WriteString("## Taxonomy\n\n")
70		b.WriteString("Top-level categories are fixed. You may invent a new three-level path only under one of these categories:\n\n")
71	
72		categories := make([]string, 0, len(taxonomy.Categories))
73		for category := range taxonomy.Categories {
74			categories = append(categories, category)
75		}
76		sort.Strings(categories)
77		for _, category := range categories {
78			fmt.Fprintf(&b, "- `%s` — %s\n", category, taxonomy.Categories[category])
79		}
80	
81		if len(taxonomy.Paths) > 0 {
82			b.WriteString("\nKnown paths (prefer these):\n\n")
83			paths := append([]factPathDef(nil), taxonomy.Paths...)
84			sort.Slice(paths, func(i, j int) bool { return paths[i].Path < paths[j].Path })
85			for _, def := range paths {
86				if def.Description != "" {
87					fmt.Fprintf(&b, "- `%s` — %s\n", def.Path, def.Description)
88				} else {
89					fmt.Fprintf(&b, "- `%s`\n", def.Path)
90				}
91			}
92		}
93		return b.String()
94	}
95	
96	// distillAgentCommandArgs builds the argv that runs the seed agent with the
97	// rendered distillation prompt. It mirrors seedAgentCommandArgs: the prompt is
98	// the agent's system prompt and the transcript chunk is supplied on stdin. The
99	// no-agent mode ("none") has no command — distillation is agent-required.
100	func distillAgentCommandArgs(agent string, agentCommand []string, prompt string) ([]string, error) {
101		switch agent {
102		case "command":
103			if len(agentCommand) == 0 {
104				return nil, errors.New("--agent-command is required when --agent command")
105			}
106			return append([]string(nil), agentCommand...), nil
107		case "codex":
108			return []string{"codex", "exec", "--skip-git-repo-check", "--ephemeral", "--ignore-user-config", "--ignore-rules", "--sandbox", "read-only", prompt}, nil
109		case "claude-code":
110			return []string{"claude", "--print", "--no-session-persistence", "--setting-sources", "user", "--strict-mcp-config", "--mcp-config", "{\"mcpServers\":{}}", "--disable-slash-commands", "--permission-mode", "dontAsk", "--tools", "", "--system-prompt", prompt}, nil
111		case "none", "":
112			return nil, errors.New("distillation requires an agent; --agent none has nothing to run")
113		default:
114			return nil, fmt.Errorf("unsupported --agent %q", agent)
115		}
116	}
117	
118	// distilledFactsFromOutput parses the agent's line-based output for one
119	// transcript chunk into fact records. Each emitted line is
120	// `path[,path]<TAB>fact`. Lines are dropped (with a warning) when they have no
121	// tab, no syntactically valid path, or no path whose top-level category exists
122	// in the active taxonomy — the taxonomy's top levels are fixed, so a path under
123	// an unknown category cannot be trusted. Output is capped at factsMaxPerChunk;
124	// extra lines are dropped with a warning so a runaway agent cannot flood the
125	// store.
126	//
127	// Every produced record cites the supplied anchor as its provenance and is
128	// stamped origin=distilled, status=active. Ids are content-derived, so the same
129	// statement from the same chunk is idempotent across reruns.
130	func distilledFactsFromOutput(output string, taxonomy factTaxonomy, anchor factAnchor, branch string, now time.Time) ([]factRecord, []string) {
131		var records []factRecord
132		var warnings []string
133		capped := false
134		for _, raw := range strings.Split(output, "\n") {
135			line := strings.TrimRight(raw, "\r")
136			if strings.TrimSpace(line) == "" {
137				continue
138			}
139			if !strings.ContainsRune(line, '\t') {
140				// Prose / preamble the template forbids; ignore quietly unless it
141				// looks like an attempted fact (contains a path-like token).
142				if strings.Contains(line, ".") && strings.Contains(line, " ") {
143					warnings = append(warnings, "dropped line without tab separator: "+truncateString(strings.TrimSpace(line), 120))
144				}
145				continue
146			}
147			rawPaths, text := splitFactLine(line)
148			if text == "" {
149				continue
150			}
151			paths := normalizeFactPaths(rawPaths)
152			paths = filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
153			if len(paths) == 0 {
154				warnings = append(warnings, "dropped fact with no valid taxonomy path: "+truncateString(text, 120))
155				continue
156			}
157			if len(records) >= factsMaxPerChunk {
158				capped = true
159				continue
160			}
161			text = truncateString(text, distillFactMaxTextSize)
162			records = append(records, factRecord{
163				ID:         factRecordID(text, paths),
164				Paths:      paths,
165				Text:       text,
166				Branch:     branch,
167				Origin:     factOriginDistilled,
168				Status:     factStatusActive,
169				Provenance: []factAnchor{anchor},
170				CreatedAt:  now,
171				UpdatedAt:  now,
172			})
173		}
174		if capped {
175			warnings = append(warnings, fmt.Sprintf("chunk produced more than %d facts; extra lines dropped", factsMaxPerChunk))
176		}
177		return records, warnings
178	}
179	
180	// splitFactLine separates a distill output line into its path tokens and fact
181	// text. The template specifies `path[,path]<TAB>fact`, but agents sometimes
182	// separate multiple paths with tabs instead of commas (`path<TAB>path<TAB>fact`),
183	// which would otherwise leak a path into the fact text. It therefore consumes
184	// leading tab-separated fields for as long as each is a path-block (comma-joined
185	// valid paths, no prose), and treats the remainder as the fact. Prose cannot
186	// match the strict path pattern (it contains spaces), so a fact is never
187	// mistaken for a path.
188	func splitFactLine(line string) ([]string, string) {
189		fields := strings.Split(line, "\t")
190		var paths []string
191		i := 0
192		for i < len(fields)-1 { // always leave at least one field for the text
193			field := strings.TrimSpace(fields[i])
194			if !fieldLooksLikePaths(field) {
195				break
196			}
197			paths = append(paths, strings.Split(field, ",")...)
198			i++
199		}
200		text := strings.TrimSpace(strings.Join(fields[i:], " "))
201		return paths, text
202	}
203	
204	// fieldLooksLikePaths reports whether a tab-separated field is entirely a
205	// path-block: one or more comma-joined, syntactically valid taxonomy paths.
206	func fieldLooksLikePaths(field string) bool {
207		if field == "" {
208			return false
209		}
210		for _, part := range strings.Split(field, ",") {
211			if !validFactPath(strings.ToLower(strings.TrimSpace(part))) {
212				return false
213			}
214		}
215		return true
216	}
217	
218	// filterFactPathsByTaxonomy keeps only paths whose top-level category exists in
219	// the taxonomy, recording a warning for each dropped path. Paths are already
220	// syntactically valid (normalizeFactPaths ran first).
221	func filterFactPathsByTaxonomy(paths []string, taxonomy factTaxonomy, warnings *[]string) []string {
222		tops := factTaxonomyTopLevels(taxonomy)
223		kept := paths[:0:0]
224		for _, path := range paths {
225			if _, ok := tops[factTopLevel(path)]; ok {
226				kept = append(kept, path)
227				continue
228			}
229			*warnings = append(*warnings, fmt.Sprintf("dropped path under unknown category: %s", path))
230		}
231		return kept
232	}
