9	// loadAllFactBranches scans the facts directory and returns every stored fact
10	// grouped by the branch recorded on each record (not the on-disk slug, which is
11	// lossy). It is the basis for rebuilding the manifest after a single-branch
12	// mutation and for whole-store operations like gc.
13	func loadAllFactBranches(brainDir string) (map[string][]factRecord, error) {
14		root := filepath.Join(brainDir, factsDirName)
15		entries, err := os.ReadDir(root)
16		if err != nil {
17			if os.IsNotExist(err) {
18				return map[string][]factRecord{}, nil
19			}
20			return nil, err
21		}
22		byBranch := map[string][]factRecord{}
23		for _, entry := range entries {
24			if !entry.IsDir() {
25				continue
26			}
27			records, err := parseFactsFile(filepath.Join(root, entry.Name(), factsFileName))
28			if err != nil {
29				return nil, err
30			}
31			for _, record := range records {
32				byBranch[record.Branch] = append(byBranch[record.Branch], record)
33			}
34		}
35		return byBranch, nil
36	}
